Cho đồ thị như hình dưới, hỏi đường thẳng trên đồ thị biểu diễn miền nghiệm của phương trình nào? 

\choice
{ $ - 2 x + y - 3=0$ }
   { $- 2 x - y + 3=0$ }
     { $2 x + y - 3=0$ }
    { \True $ - 2 x - y - 3=0$ }
}{
\begin{tikzpicture}[line join=round, line cap=round,>=stealth,thick,scale=0.6]
    \tikzset{every node/.style={scale=0.9}}
    %\draw[gray!20](-6,-6.5)grid(6,6.5);
    \draw[->] (-6,0)--(6,0) node[below left] {$x$};
    \draw[->] (0,-6.5)--(0,6.5) node[below left] {$y$};
    \draw (0,0) node [below left] {\footnotesize $O$};
     \foreach \x in {-4,-3,-2,-1,1,2,3,4}
    \draw[thin] (\x,1pt)--(\x,-1pt) node [below] {\footnotesize$\x$};
    \foreach \y in {-4,-3,-2,-1,1,2,3,4}
    \draw[thin] (1pt,\y)--(-1pt,\y) node [left] {\footnotesize$\y$};
    \begin{scope}
     \clip (-6.5,-6.5) rectangle (6.5,6.5);
    \draw[thick,blue][samples=200,domain=-6.5:6.5,smooth,variable=\x] plot (\x,{-2*(\x)+-3});
    \end{scope}
    \end{tikzpicture}
}
\loigiai{
Đường thẳng biểu diễn miền nghiệm của phương trình $ - 2 x - y - 3=0$ vì ta thấy đường thẳng đi qua 2 điểm có toạ độ là $\left(0;-3\right) $ và $\left(- \dfrac{3}{2};0\right) $ Thay các cặp số này vào các phương án ta thấy chỉ có phương trình $ - 2 x - y - 3=0$ là thoả mãn.
}\end{ex}

